import os, re, sys, json

ROOT = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/10_cluster/C7/public/snapshots/s12"
OUT  = os.path.join(os.environ["TMPDIR"], "i041")

src_exts = (".c", ".h")

# regexes for softirq-context registrations
tasklet_reg = [
    re.compile(r'\btasklet_init\s*\('),
    re.compile(r'\bDECLARE_TASKLET(?:_DISABLED)?\s*\('),
]
napi_reg = [
    re.compile(r'\bnetif_napi_add\s*\('),
]
napi_sched = re.compile(r'\bnapi_schedule(?:_irq)?\s*\(')

files = []
for dirpath, dirnames, filenames in os.walk(ROOT):
    dirnames[:] = [d for d in dirnames if d not in ("Documentation","scripts","tools","samples",".git")]
    for fn in filenames:
        if fn.endswith(src_exts):
            files.append(os.path.join(dirpath, fn))
print("total source files:", len(files), file=sys.stderr)

tasklet_files = {}
napi_files = {}
for p in files:
    try:
        t = open(p, encoding="utf-8", errors="replace").read()
    except OSError:
        continue
    if any(rx.search(t) for rx in tasklet_reg):
        rel = os.path.relpath(p, ROOT)
        tasklet_files[rel] = t
    if any(rx.search(t) for rx in napi_reg) or napi_sched.search(t):
        rel = os.path.relpath(p, ROOT)
        napi_files[rel] = t

print("files with tasklet registration:", len(tasklet_files), file=sys.stderr)
print("files with napi add/schedule:", len(napi_files), file=sys.stderr)
json.dump({"tasklet": sorted(tasklet_files), "napi": sorted(napi_files)}, open(os.path.join(OUT, "registration_files.json"), "w"), indent=1)

# helper: extract function name from a call's first argument
def first_arg(text, start):
    # start = index of '('
    depth = 0
    i = start
    n = len(text)
    while i < n:
        c = text[i]
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
            if depth == 0:
                break
        i += 1
    return text[start+1:i]

IDENT = re.compile(r'^\s*([A-Za-z_]\w*)\s*$')

def extract_call_argname(m):
    """m: match object of a call like tasklet_init(...)"""
    argtxt = first_arg(m.string, m.end()-1)
    parts = split_args(argtxt)
    return [p.strip() for p in parts]

def split_args(s):
    args, depth, cur = [], 0, ""
    for ch in s:
        if ch in "([{":
            depth += 1
        elif ch in ")]}":
            depth -= 1
        if ch == ',' and depth == 0:
            args.append(cur); cur = ""
        else:
            cur += ch
    if cur.strip():
        args.append(cur)
    return args

records = []  # (relpath, kind, symbol, line, calltext)
for rel, text in list(tasklet_files.items()):
    for lineno, line in enumerate(text.splitlines(), 1):
        for rx in tasklet_reg:
            for m in rx.finditer(line):
                args = extract_call_argname(m)
                # tasklet_init(t, callback, data) -> callback is arg2; DECLARE_TASKLET(name, func, data) -> func is arg2
                cb = args[1] if len(args) >= 2 else "?"
                mm = IDENT.match(cb)
                records.append((rel, "tasklet", cb if mm else cb, lineno, m.group(0)))
for rel, text in list(napi_files.items()):
    for lineno, line in enumerate(text.splitlines(), 1):
        for m in re.finditer(r'\bnetif_napi_add\s*\(', line):
            args = extract_call_argname(m)
            # historical: netif_napi_add(dev, napi, poll, weight) or new (dev, napi, poll)
            cb = args[2] if len(args) >= 3 else "?"
            records.append((rel, "napi", cb, lineno, m.group(0)))

with open(os.path.join(OUT, "callback_regs.txt"), "w") as f:
    for r in records:
        f.write(f"{r[0]}:{r[3]} {r[1]} callback={r[2]} :: {r[4]}\n")
print("callback registrations:", len(records), file=sys.stderr)
EOF
